using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Expenses;using Namaa.Api.Extensions;using Namaa.Application.Expenses.Commands.CreateExpense;using Namaa.Application.Expenses.Commands.UpdateExpense;using Namaa.Application.Expenses.Queries.GetExpenseById;using Namaa.Application.Expenses.Queries.GetExpenses;namespace Namaa.Api.Controllers;[ApiController][Route("api/expenses")]public sealed class ExpensesController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreateExpenseRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreateExpenseCommand(request.ExpenseNumber,request.ExpenseDate,request.Category,request.Description,request.Amount,request.ProjectId),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetExpensesQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetExpenseByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateExpenseRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateExpenseCommand(id,request.ExpenseDate,request.Category,request.Description,request.Amount,request.ProjectId),cancellationToken)).ToActionResult(this);}
